INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8101, '2 Samuel 22:16', '2 Samuel', 22, 16, '&nbsp;د سمندر بېخ راڅرګند شو. او د زمکې بنيادونه راښکاره شول کله چې مالِک خُدائ خپل دشمنان ورټل او په غصه کښې په هغوئ باندې وغورېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8102, '2 Samuel 22:17', '2 Samuel', 22, 17, '&nbsp;نو مالِک خُدائ د بره نه راورسېدو او زۀ يې ونيولم، هغۀ د ډېرو اوبو نه بهر راوويستلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8103, '2 Samuel 22:18', '2 Samuel', 22, 18, '&nbsp;هغۀ زۀ د خپلو زورَورو دشمنانو نه بچ کړم او د هغه ټولو نه چې زما نه يې نفرت کولو، هغوئ زما دپاره ډېر زيات طاقتور وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8104, '2 Samuel 22:19', '2 Samuel', 22, 19, '&nbsp;کله چې زۀ په تکليف کښې وم نو هغوئ په ما حمله وکړه، خو مالِک خُدائ زۀ بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8105, '2 Samuel 22:20', '2 Samuel', 22, 20, '&nbsp;هغۀ زۀ د خطرې نه راوويستلم هغۀ زۀ ځکه بچ کړم چې زما نه رضا وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8106, '2 Samuel 22:21', '2 Samuel', 22, 21, '&nbsp;مالِک خُدائ ما له اجر راکوى ځکه چې زۀ هغه څۀ کوم چې څۀ حق وى، هغه ما له برکت راکوى ځکه چې زۀ بې‌ګناه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8107, '2 Samuel 22:22', '2 Samuel', 22, 22, '&nbsp;ما د مالِک خُدائ قانون منلے دے، زۀ د خُدائ پاک نه نۀ يم اوړېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8108, '2 Samuel 22:23', '2 Samuel', 22, 23, '&nbsp;ما د هغۀ ټول قوانين منلى دى، ما د هغۀ د حُکمونو نافرمانى نۀ ده کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8109, '2 Samuel 22:24', '2 Samuel', 22, 24, '&nbsp;هغۀ ته پته ده چې زۀ صفا يم، ځکه چې ما ځان د ګناه نه ساتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8110, '2 Samuel 22:25', '2 Samuel', 22, 25, '&nbsp;او هغه ما له ځکه اجر راکوى چې هغه څۀ کوم چې صحيح وى. ځکه چې هغۀ ته پته ده چې زۀ بې‌ګناه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8111, '2 Samuel 22:26', '2 Samuel', 22, 26, '&nbsp;مالِکه خُدايه، تۀ د هغه خلقو سره وفادار يې چې څوک ستا وفادار وى، او چې څوک ښۀ وى نو تۀ د هغوئ سره ښۀ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8112, '2 Samuel 22:27', '2 Samuel', 22, 27, '&nbsp;چې څوک صفا خلق وى نو تۀ د هغوئ سره صفا يې، خو تۀ د بدعملو سره سخت يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8113, '2 Samuel 22:28', '2 Samuel', 22, 28, '&nbsp;تۀ هغه څوک بچ کوې چې څوک عاجز وى. خو تۀ هغه څوک عاجزان کوې چې څوک مغرور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8114, '2 Samuel 22:29', '2 Samuel', 22, 29, '&nbsp;مالِکه خُدايه، تۀ زما رڼا يې، تۀ زما تيارې لرې کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8115, '2 Samuel 22:30', '2 Samuel', 22, 30, '&nbsp;تۀ ما له طاقت راکوې چې په دشمن حمله وکړم او طاقت راکوې چې د هغوئ په دېوالونو باندې ورواوړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8116, '2 Samuel 22:31', '2 Samuel', 22, 31, '&nbsp;دا خُدائ پاک دے، چې د هغۀ کارونه څومره مکمل دى، د هغۀ کلام څومره اعتبارى دے. هغه د ډال په شان دے د هغه هر چا دپاره دے چې څوک يې پناه لټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8117, '2 Samuel 22:32', '2 Samuel', 22, 32, '&nbsp;مالِک خُدائ يواځې خُدائ پاک دے خُدائ پاک يواځې زمونږ د پناه ځائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8118, '2 Samuel 22:33', '2 Samuel', 22, 33, '&nbsp;دا خُدائ پاک زما مضبوط د پناه ځائ دے، هغه زما لاره سموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8119, '2 Samuel 22:34', '2 Samuel', 22, 34, '&nbsp;هغه ما د هوسۍ په شان تېزوى. هغه ما په غرونو کښې په حِفاظت کښې ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8120, '2 Samuel 22:35', '2 Samuel', 22, 35, '&nbsp;هغه ما له د جنګ تربيت راکوى، نو چې داسې زۀ د ټولو نه مضبوط غشے اوچلوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8121, '2 Samuel 22:36', '2 Samuel', 22, 36, '&nbsp;مالِکه خُدايه، ما بچ کړه او زما حِفاظت وکړه، ستا د مدد په وجه زۀ تکړه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8122, '2 Samuel 22:37', '2 Samuel', 22, 37, '&nbsp;تا زما دپاره لار پراخه کړې ده، نو ځکه زما پښې کله هم نۀ دى ښوئېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8123, '2 Samuel 22:38', '2 Samuel', 22, 38, '&nbsp;زۀ په خپل دشمن پسې ځم او شکست ورکوم، تر هغې پورې نۀ ودرېږم چې تباه کړې مې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8124, '2 Samuel 22:39', '2 Samuel', 22, 39, '&nbsp;زۀ هغوئ وغورزوم او هغوئ پاڅېدے نۀ شى، هغوئ زما د پښو لاندې پرېوتى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8125, '2 Samuel 22:40', '2 Samuel', 22, 40, '&nbsp;تۀ ما له د جنګ دپاره طاقت راکوې او په خپلو دشمنانو باندې فتح راکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8126, '2 Samuel 22:41', '2 Samuel', 22, 41, '&nbsp;تۀ زما نه زما دشمن زغلوې، او چې څوک زما نه نفرت کوى نو هغه تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8127, '2 Samuel 22:42', '2 Samuel', 22, 42, '&nbsp;هغوئ د مدد دپاره وکتل، خو هيچا هم هغوئ بچ نۀ کړل، هغوئ مالِک خُدائ ته فرياد وکړو، خو هغۀ جواب ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8128, '2 Samuel 22:43', '2 Samuel', 22, 43, '&nbsp;ما هغوئ مېده کړل او هغوئ د خاورې په شان شول، د کوڅې د خاورې په شان ما په هغوئ پښه راښکله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8129, '2 Samuel 22:44', '2 Samuel', 22, 44, '&nbsp;تا زۀ د خپلو سرکشو خلقو نه بچ کړم او زما بادشاهى دې په قومونو باندې په خپل ځائ وساتله، کوم خلق چې ما نۀ پېژندل هغوئ زما د بادشاهۍ لاندې راغلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8130, '2 Samuel 22:45', '2 Samuel', 22, 45, '&nbsp;مسافر زما په وړاندې ټيټيږى، کله چې هغوئ زما نه خبر شى، هغوئ زما تابعدارى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8131, '2 Samuel 22:46', '2 Samuel', 22, 46, '&nbsp;هغوئ خپله حوصله بائيلى او د خپلو محفوظو ځايونو نه په ريږدېدو راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8132, '2 Samuel 22:47', '2 Samuel', 22, 47, '&nbsp;مالِک خُدائ ژوندے دے. زما د حِفاظت کوونکى ثناء صِفت دې وى. د هغه تکړه خُدائ پاک د لويئ اِعلان وکړئ چې هغۀ زۀ بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8133, '2 Samuel 22:48', '2 Samuel', 22, 48, '&nbsp;هغه ما له په خپلو دشمنانو باندې فتح راکوى، هغه قومونه زما لاندې راولى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8134, '2 Samuel 22:49', '2 Samuel', 22, 49, '&nbsp;او هغه ما د خپل دشمن نه بچ کوى. اے مالِکه خُدايه، ما له په خپلو دشمنانو باندې فتح راکړه او ما د ظالمانو سړو نه بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8135, '2 Samuel 22:50', '2 Samuel', 22, 50, '&nbsp;نو چې په قومونو کښې زۀ ستا ثناء صِفت وايم، او زۀ به ستا د نوم ثناء صِفت بيانوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8136, '2 Samuel 22:51', '2 Samuel', 22, 51, '&nbsp;خُدائ پاک خپل بادشاه له فتحې ورکوى، هغۀ چې څوک خوښ کړے دے نو هغۀ ورته خپله مستقله مينه ښودلې ده، داؤد او د هغۀ اولاد ته يې همېشه ښائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8137, '2 Samuel 23:1', '2 Samuel', 23, 1, '&nbsp;د يَسى زوئ داؤد هغه سړے وو چې خُدائ پاک ورله شان او شوکت ورکړے وو، چې د يعقوب خُدائ پاک هغه د دې دپاره خوښ کړو چې بادشاه شى او هغه د بنى اِسرائيلو دپاره مشهور ثناء خوان هم وو. د داؤد آخرى خبرې دا وې:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8138, '2 Samuel 23:2', '2 Samuel', 23, 2, '&nbsp;”د مالِک خُدائ روح زما په ذريعه خبرې کوى، د هغۀ پېغام زما په ژبه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8139, '2 Samuel 23:3', '2 Samuel', 23, 3, '&nbsp;د بنى اِسرائيلو خُدائ پاک فرمائيلى دى، د بنى اِسرائيلو حِفاظت کوونکى ما ته فرمائيلى دى، ”هغه بادشاه چې په اِنصاف سره بادشاهى کوى، کوم چې د خُدائ پاک په يره کښې بادشاهى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8140, '2 Samuel 23:4', '2 Samuel', 23, 4, '&nbsp;هغه داسې دے لکه چې بې‌وريځو سحر کښې نمر پړقيږى، هغه نمر چې د باران نه پس واښۀ ځلوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8141, '2 Samuel 23:5', '2 Samuel', 23, 5, '&nbsp;نو داسې به خُدائ پاک زما اولاد له برکت ورکړى، ځکه چې هغۀ زما سره د تل دپاره لوظ کړے دے، يو داسې لوظ چې هغه به نۀ ماتيږى، يوه وعده چې نۀ به بدليږى. زما بلکل هم دغه خواهش دے، دا به زما خلاصون وى، او بې‌شکه خُدائ پاک به داسې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8142, '2 Samuel 23:6', '2 Samuel', 23, 6, '&nbsp;خو بد کاره خلق د غورزولے شوو ازغو په شان وى، چې هيڅ څوک يې هم په خالى لاسونو سره نۀ شى راخستلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8143, '2 Samuel 23:7', '2 Samuel', 23, 7, '&nbsp;تۀ به د دې دپاره د اوسپنې آوزار يا د نېزې نه کار اخلې، هغوئ به بېخى وسوزولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8144, '2 Samuel 23:8', '2 Samuel', 23, 8, '&nbsp;د داؤد د مشهورو فوجيانو نومونه دا دى: وړومبے د تحُکمون يوشيب بيشبت وو، کوم چې د درېو مشر وو، هغۀ د خپلې نېزې سره د اتو سوو خِلاف جنګ وکړو او هغوئ ټول يې په يو جنګ کښې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8145, '2 Samuel 23:9', '2 Samuel', 23, 9, '&nbsp;د هغه درېو مشهورو نه دوېم د اخيو د قبيلې د دودو زوئ اِلى‌عزر وو. يوه ورځ چې فلستيان راغونډ وُو نو هغۀ او داؤد ورته وفرمائيل چې زمونږ سره جنګ وکړئ. نو اِسرائيليان ټول وتښتېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8146, '2 Samuel 23:10', '2 Samuel', 23, 10, '&nbsp;خو هغه ټينګ شو او د فلستيانو سره يې تر دې پورې جنګ وکړو چې لاس يې کار پرېښودو او خپلې تُورې له يې نۀ شو وروړلے. مالِک خُدائ په هغه ورځ باندې لويه فتح وموندله. کله چې دا ختم شو، نو اِسرائيليان اِلى‌عزر له راواپس شول او د مړو دشمنانو نه يې زغرې وويستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8147, '2 Samuel 23:11', '2 Samuel', 23, 11, '&nbsp;د هغه درېو مشهورو نه يو د حرار د اجى زوئ سمه وو. فلستيان لحى کښې راغونډ شوى وُو چرته چې د دالو يو پټے وو. اِسرائيليان د فلستيانو نه وتښتېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8148, '2 Samuel 23:12', '2 Samuel', 23, 12, '&nbsp;خو سمه په پټى کښې ټينګ شو، د دې حِفاظت يې وکړو او فلستيان يې ووژل. مالِک خُدائ په هغه ورځ باندې لويه فتح وموندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8149, '2 Samuel 23:13', '2 Samuel', 23, 13, '&nbsp;لَو شروع کېدو ته په نزدې وخت کښې د هغه دېرشو کسانو نه درې د عدولام غار ته لاړل، چرته چې داؤد وو، په دې وخت کښې د فلستيانو فوج د رفائيم په وادۍ کښې خېمې لګولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8150, '2 Samuel 23:14', '2 Samuel', 23, 14, '&nbsp;په دې وخت کښې داؤد په يو محفوظ ځائ کښې وو او د فلستيانو يوې قبيلې بيت‌لحم قبضه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8151, '2 Samuel 23:15', '2 Samuel', 23, 15, '&nbsp;داؤد ډېر زيات تږے وو او وې فرمائيل، ”زما ډېر ارمان دے چې څوک د بيت‌لحم د دروازې سره کوهى نه ما له څښلو له لږې اوبۀ راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8152, '2 Samuel 23:16', '2 Samuel', 23, 16, '&nbsp;هغه درې مشهور فوجيان د فلستيانو کېمپ ته وردننه شول، د کوهى نه يې اوبۀ راوويستلې او داؤد له يې راوړې. خو هغۀ دا ونۀ څښلې، او د څښلو په ځائ يې مالِک خُدائ ته د نذرانې په توګه توئ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8153, '2 Samuel 23:17', '2 Samuel', 23, 17, '&nbsp;او وې فرمائيل، ”مالِکه خُدايه، زۀ دا هيڅکله نۀ شم څښلے. دا به داسې وى لکه چې زۀ د دې سړو وينې څښم چا چې خپل ژوند په خطره کښې واچولو.“ نو هغۀ د دې څښلو نه اِنکار وکړو. دا د هغه درېو مشهورو فوجيانو د بهادرۍ کارنامې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8154, '2 Samuel 23:18', '2 Samuel', 23, 18, '&nbsp;د يوآب ورور ابيشے چې د هغۀ مور ضروياه وه د هغه دېرشو مشر وو. هغۀ د خپلې نېزې سره د درېو سوو سړو خِلاف جنګ وکړو او وې وژل او د دې په وجه هغه د هغه درېو کسانو په شان مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8155, '2 Samuel 23:19', '2 Samuel', 23, 19, '&nbsp;نو هغه د هغه درېو نه زيات عزتمند شو او د هغوئ مشر شو، خو هغه په هغه درېو کسانو کښې شمېر نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8156, '2 Samuel 23:20', '2 Samuel', 23, 20, '&nbsp;د يهويدع زوئ بناياه يو بل مشهور فوجى وو او دے د قبضئيل اوسېدونکے وو، هغۀ ډېرې د بهادرۍ کارنامې وکړې چې په کښې د هغه دوو لويو موآبيانو جنګ کوونکو وژل هم شامل وُو. يوه ورځ چې واوره ورېدله هغه کندې ته کوز شو او يو زمرے يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8157, '2 Samuel 23:21', '2 Samuel', 23, 21, '&nbsp;هغۀ يو مِصرے هم ووژلو، يو غټ سړے چې نېزه ورسره وه. بناياه په هغۀ باندې د امسا سره حمله وکړه، د مِصرى د لاس نه يې نېزه واخستله او په دې باندې يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8158, '2 Samuel 23:22', '2 Samuel', 23, 22, '&nbsp;دا د هغه بناياه کارنامې دى چې د هغه درېو تکړه فوجيانو په شان مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8159, '2 Samuel 23:23', '2 Samuel', 23, 23, '&nbsp;هغه په ټولو کښې ښۀ تکړه وو، خو هغه په هغه درېو کښې نۀ شو شمېرلے. داؤد هغه د خپلو محافظانو مشر مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8160, '2 Samuel 24:1', '2 Samuel', 24, 1, '&nbsp;مالِک خُدائ بنى اِسرائيلو ته يو ځل بيا غصه شو او د داؤد په ذريعه يې په هغوئ مصيبت راوستلو. مالِک خُدائ هغۀ ته وفرمائيل، ”لاړ شه او د اِسرائيل او د يهوداه خلق وشمېره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8161, '2 Samuel 24:2', '2 Samuel', 24, 2, '&nbsp;نو داؤد د خپل لښکر مشر يوآب له حُکم ورکړو، ”د خپلو آفسرانو سره د بنى اِسرائيلو ټولو قبيلو ته لاړ شه د يو سر نه تر بل سره پورې وګرځه او خلق وشمېره. زۀ دا معلومول غواړم چې هغوئ څومره دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8162, '2 Samuel 24:3', '2 Samuel', 24, 3, '&nbsp;خو يوآب بادشاه ته ووئيل، ”بادشاه سلامت، مالِک خُدائ ستا خُدائ پاک دې بنى اِسرائيليان د اوس نه يو په سل نور هم زيات کړى او ژوندے اوسې چې تۀ يې وګورې. خو بادشاه سلامت، تۀ داسې کول ولې غواړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8163, '2 Samuel 24:4', '2 Samuel', 24, 4, '&nbsp;خو بادشاه په يوآب او د هغۀ په آفسرانو باندې د هغۀ حُکم ومنلو، هغوئ د هغۀ د حضور نه روان شول او د بنى اِسرائيلو خلقو شمېرلو له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8164, '2 Samuel 24:5', '2 Samuel', 24, 5, '&nbsp;هغوئ د اُردن سيند نه واوړېدل او د عروعير جنوبى طرف ته يې خېمې ولګولې، دا ښار د جاد په علاقه کښې د يعزير د وادۍ په مينځ کښې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8165, '2 Samuel 24:6', '2 Samuel', 24, 6, '&nbsp;او د حِتيانو په علاقه کښې جِلعاد او قادِس ته روان وُو. بيا هغوئ دان ته لاړل او د دان نه هغوئ نمرپرېواتۀ طرف صيدا ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8166, '2 Samuel 24:7', '2 Samuel', 24, 7, '&nbsp;بيا هغوئ جنوبى طرف ته د پَخو دېوالونو ښار صور ته لاړل او هم هغسې د حِويانو او کنعانيانو ټولو ښارونو ته هم لاړل او په آخر کښې د يهوداه په جنوبى برخه کښې بيرسبع ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8167, '2 Samuel 24:8', '2 Samuel', 24, 8, '&nbsp;نو نهۀ مياشتې او شل ورځې پس هغوئ يروشلم ته راواپس شول، چې په ټول مُلک کښې يې سفر کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8168, '2 Samuel 24:9', '2 Samuel', 24, 9, '&nbsp;هغوئ بادشاه له د هغه ټولو سړو شمېر ورکړو چا چې جنګ کولے شو، اتۀ لاکه سړى په اِسرائيل کښې او پينځۀ لاکه په يهوداه کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8169, '2 Samuel 24:10', '2 Samuel', 24, 10, '&nbsp;خو چې کله داؤد مردم‌شمارى وکړه نو خپل ضمير هغه ملامته کول شروع کړل او هغۀ مالِک خُدائ ته وفرمائيل، ”ما چې څۀ کړى دى نو دا مې يوه سخته ګناه کړې ده، مالِکه خُدايه، زما غلطى معاف کړه. ما د کم عقلتوب کار کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8170, '2 Samuel 24:13', '2 Samuel', 24, 13, '&nbsp;جاد هغۀ له لاړو او چې مالِک خُدائ څۀ فرمائيلى وُو هغه يې ورته وفرمائيل او تپوس يې ترې نه وکړو، ”په دې کښې ستا کوم يو خوښ دے؟ ستا په مُلک کښې درې کاله قحط وى يا درې مياشتې چې خپل دشمن نه منډې وهې يا چې درې ورځې ستا په مُلک وبا راشى؟ اوس په دې باندې سوچ وکړه او ما ته ووايه چې مالِک خُدائ چا چې زۀ رالېږلے يم کوم يو جواب يوسم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8171, '2 Samuel 24:14', '2 Samuel', 24, 14, '&nbsp;داؤد جواب ورکړو، ”زۀ د نااُميدۍ په حالت کښې يم. خو زۀ دا نۀ غواړم چې ما له انسان سزا راکړى. پرېږده چې مالِک خُدائ په خپله مونږ له سزا راکړى، ځکه چې هغه رحمان او رحيم دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8172, '2 Samuel 24:15', '2 Samuel', 24, 15, '&nbsp;نو مالِک خُدائ په بنى اِسرائيلو باندې يوه وبا راولېږله، چې د هغه سحر نه واخله تر هغه وخت پورې وه چې کوم يې خوښ کړے وو. د مُلک د يو سر نه تر بل سره پورې اويا زره بنى اِسرائيليان مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8173, '2 Samuel 24:16', '2 Samuel', 24, 16, '&nbsp;کله چې د مالِک خُدائ فرښته د يروشلم په تباه کولو باندې وه، نو مالِک خُدائ د خلقو سزا په حقله خپله فېصله بدله کړه او هغه فرښتې ته يې وفرمائيل کومې چې هغوئ وژل، ”بس دے، دا دومره ورله ډېر دى.“ فرښته د يو يبوسى اروناه د درمند سره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8174, '2 Samuel 24:17', '2 Samuel', 24, 17, '&nbsp;داؤد فرښته وليده چې هغې خلق وژل او مالِک خُدائ ته يې وفرمائيل، ”زۀ ګناهګار يم. زۀ هغه کس يم چا چې غلطى کړې ده. دې عاجزو خلقو څۀ کړى دى؟ تا له په کار دى چې ما او زما خاندان له سزا راکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8175, '2 Samuel 24:18', '2 Samuel', 24, 18, '&nbsp;هم په هغه ورځ جاد داؤد له ورَغلو او ورته يې وفرمائيل، ”د اروناه درمند ته وخېژه او مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8176, '2 Samuel 24:19', '2 Samuel', 24, 19, '&nbsp;نو داؤد د مالِک خُدائ حُکم ومنلو او چې څنګه جاد ورته وئيلى وُو هغه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8177, '2 Samuel 24:20', '2 Samuel', 24, 20, '&nbsp;اروناه لاندې وکتل او وې ليدل چې بادشاه او د هغۀ آفسران راروان وُو. هغه د داؤد په مخکښې پړمخې پرېوتو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8178, '2 Samuel 24:21', '2 Samuel', 24, 21, '&nbsp;او تپوس يې وکړو، ”بادشاه سلامت، تۀ دلته د څۀ دپاره راغلې؟“ داؤد ورته وفرمائيل، ”د دې دپاره چې ستا درمند واخلم او مالِک خُدائ ته يوه قربان‌ګاه جوړه کړم، دا د دې دپاره چې وبا ودريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8179, '2 Samuel 24:22', '2 Samuel', 24, 22, '&nbsp;اروناه ورته ووئيل، ”بادشاه سلامت، وايې خله او چې څۀ دې خوښ وى نو هغه مالِک خُدائ ته پېش کړه. دا غوَيى دى چې په قربان‌ګاه باندې به يې د نذرانې په توګه وسوزوې، د هغوئ جغونه او د غوبل تختې دا دى چې د سوزولو د لرګو په توګه يې استعمال کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8180, '2 Samuel 24:23', '2 Samuel', 24, 23, '&nbsp;اروناه هر څۀ بادشاه له ورکړل او ورته يې ووئيل، ”مالِک خُدائ ستا خُدائ پاک دې ستا نذرانه قبوله کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8181, '2 Samuel 24:24', '2 Samuel', 24, 24, '&nbsp;خو بادشاه ورته وفرمائيل، ”نه، زۀ به د دې قيمت درکوم. زۀ به مالِک خُدائ خپل خُدائ پاک ته هغه څۀ په نذرانه کښې نۀ پېش کوم چې مفت مِلاو شى.“ نو هغۀ درمند او غوَيى د سپينو زرو په پنځوسو سيکو باندې واخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8182, '2 Samuel 24:25', '2 Samuel', 24, 25, '&nbsp;بيا هغۀ مالِک خُدائ ته يوه قربان‌ګاه جوړه کړه او سوزېدونکې نذرانې او د سلامتۍ نذرانې يې پېش کړې. مالِک خُدائ د هغۀ سوال قبول کړو او په بنى اِسرائيلو کښې وبا بنده شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8183, '1 Kings 1:1', '1 Kings', 1, 1, '&nbsp;داؤد اوس د ډېر عُمر سړے وو، کۀ په هغۀ باندې به ډيرې بسترې واچولے شوې نو هغه به بيا هم نۀ ګرمېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8184, '1 Kings 1:2', '1 Kings', 1, 2, '&nbsp;خپلو آفسرانو هغۀ ته ووئيل، ”بادشاه سلامت، مونږ به يوه پېغله ولټوُو چې تا سره وى او ستا خِدمت کوى. هغه به ستا په څنګ کښې څملى او تا به ګرم ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8185, '1 Kings 1:3', '1 Kings', 1, 3, '&nbsp;هغوئ په ټولو بنى اِسرائيلو کښې يوې ښُکلې پېغلې پسې وګرځېدل او په شونيم کښې يې يوه داسې جينۍ پېدا کړه چې نوم يې ابى‌شاګ وو او بادشاه له يې راوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8186, '1 Kings 1:4', '1 Kings', 1, 4, '&nbsp;هغه ډېره ښائسته وه او د بادشاه خِدمت يې کولو او د هغۀ خيال يې ساتلو، خو د ښځې په توګه يې نۀ استعمالوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8187, '1 Kings 1:7', '1 Kings', 1, 7, '&nbsp;هغۀ يوآب (چې د هغۀ مور ضروياه وه) او د ابياتار اِمام سره خبره وکړه او هغوئ په دې راضى شول چې د هغۀ د خبرې ملګرتيا وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8188, '1 Kings 1:8', '1 Kings', 1, 8, '&nbsp;خو صدوق اِمام، د يهويدع زوئ بناياه، ناتن پېغمبر، سِمعى، ريعى او د داؤد محافظان د ادونياه په طرف نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8189, '1 Kings 1:9', '1 Kings', 1, 9, '&nbsp;يوه ورځ ادونياه د عين‌راجل چينې سره نزدې، د مار د ګټ سره د ګډانو، غوَيانو او د څربو سخو قربانى پېش کړه. هغۀ د داؤد بادشاه نورو زامنو او د بادشاه وزيرانو او آفسرانو له دعوت ورکړو کوم چې د يهوداه وُو چې د قربانۍ دې مېلمستيا له راشى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8190, '1 Kings 1:10', '1 Kings', 1, 10, '&nbsp;خو هغۀ خپل ناسکه ورور سليمان، ناتن پېغمبر، بناياه او د بادشاه محافظانو له دعوت ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8191, '1 Kings 1:11', '1 Kings', 1, 11, '&nbsp;ناتن د سليمان مور بت‌‌سبع له لاړو او د هغې نه يې تپوس وکړو، ”تۀ خبر نۀ يې څۀ چې د حجيت زوئ ادونياه خپل ځان بادشاه جوړ کړے دے؟ او داؤد د دې نه خبر هم نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8192, '1 Kings 1:12', '1 Kings', 1, 12, '&nbsp;کۀ تۀ خپل ژوند او خپل زوئ سليمان بچ کول غواړې نو زۀ به يوه مشوره درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8193, '1 Kings 1:13', '1 Kings', 1, 13, '&nbsp;داؤد بادشاه له فوراً لاړه شه او تپوس ترې نه وکړه چې، بادشاه سلامت، تا زما سره دا پوخ لوظ نۀ وو کړے څۀ چې زما زوئ سليمان به ستا نه پس بادشاه جوړوې؟ نو دا ادونياه ولې بادشاه شو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8194, '1 Kings 1:14', '1 Kings', 1, 14, '&nbsp;او ناتن دا هم وفرمائيل، ”چې کله تۀ د داؤد بادشاه سره خبرې کوې، نو زۀ به درشم او ستا ټولې خبرې به رښتيا کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8195, '1 Kings 1:15', '1 Kings', 1, 15, '&nbsp;نو بت‌‌سبع د بادشاه مِلاوېدو له د بادشاه کوټې ته ورغله. هغه ډېر بوډا شوے وو او شونيمى ښځې ابى‌شاګ د بادشاه خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8196, '1 Kings 1:16', '1 Kings', 1, 16, '&nbsp;بت‌‌سبع د بادشاه په مخکښې ټيټه شوه او په زمکه پړمخې پرېوته او هغۀ ترې نه تپوس وکړو، ”زۀ ستا دپاره څۀ وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8197, '1 Kings 1:17', '1 Kings', 1, 17, '&nbsp;هغې ورته ووئيل، ”بادشاه سلامت، تا د مالِک خُدائ د خپل خُدائ پاک په نوم زما سره پوخ لوظ کړے وو چې زما زوئ سليمان به ستا نه پس بادشاه وى او ستا په تخت باندې به ناست وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8198, '1 Kings 1:18', '1 Kings', 1, 18, '&nbsp;خو ګوره، ادونياه بادشاه شوے دے او صاحِبه، تۀ د دې نه خبر هم نۀ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8199, '1 Kings 1:19', '1 Kings', 1, 19, '&nbsp;هغۀ د ډېرو غوَيانو، ګډو او څربو سخو قربانى پېش کړې ده او هغۀ ستا زامنو، ابياتار اِمام او ستا د لښکر مشر يوآب له د مېلمستيا دعوت ورکړے دے، خو هغۀ ستا زوئ سليمان له دعوت نۀ دے ورکړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8200, '1 Kings 1:20', '1 Kings', 1, 20, '&nbsp;بادشاه سلامت، د بنى اِسرائيلو ټول خلق ستا په طمع دى چې هغوئ ته ووائې چې ستا نه پس به څوک بادشاه جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');